import CircuitBreaker from 'opossum';

const payments = new CircuitBreaker((order) => api.authorize(order), {
  timeout: 500,                 // abort the in-flight request, not just the await
  errorThresholdPercentage: 50, // failure rate that trips the circuit
  rollingCountTimeout: 10_000,  // the failure window (ms)
  rollingCountBuckets: 10,
  volumeThreshold: 20,          // do not trip below this many requests
  resetTimeout: 15_000,         // cooldown before the halfOpen trial
}).fallback(() => Receipt.degraded());

payments.on('open', () => metrics.increment('payments.circuit.open'));

const payments = circuitBreaker(handleAll, {
  halfOpenAfter: 15_000,                  // cooldown before the trial call
  breaker: new ConsecutiveBreaker(5),     // trip after 5 consecutive failures
});
const pipeline = wrap(retry(handleAll, { maxAttempts: 2 }), payments);

payments.onBreak(() => metrics.increment('payments.circuit.open'));

const receipt = await pipeline.execute(({ signal }) => api.authorize(order, signal));
